CREATE COLUMN TABLE "TEST_AP"."CRD2" ("CardCode" NVARCHAR(15) NOT NULL , "LineNum" INTEGER CS_INT NOT NULL , "PymCode" NVARCHAR(15), "LogInstanc" INTEGER CS_INT DEFAULT 0, "ObjType" SMALLINT CS_INT DEFAULT 2, PRIMARY KEY ("CardCode", "LineNum")) UNLOAD PRIORITY 0  AUTO MERGE ;
ALTER TABLE "TEST_AP"."CRD2" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$CardCode$PymCode$','CardCode','PymCode'));
CREATE INDEX "CRD2_CRD_PYM" ON "TEST_AP"."CRD2" ( "CardCode" ASC, "PymCode" ASC )